def squash(s: str) -> str:
    n = len(s)
    if n == 0:
        return ""
    parts = []
    i = 0
    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1
        run = j - i
        if c == "\\" or ("0" <= c <= "9"):
            token = "\\" + c
        else:
            token = c
        if run >= 3:
            parts.append(str(run))
            parts.append(token)
        else:
            parts.append(token * run)
        i = j
    return "".join(parts)
